def mergeAlternately(word1: str, word2: str) -> str:
    # Calculate lengths
    n1, n2 = len(word1), len(word2)
    result = []
    i = 0

    # Iterate while either string has characters left
    while i < n1 or i < n2:
        if i < n1:
            result.append(word1[i])
        if i < n2:
            result.append(word2[i])
        i += 1
    return ''.join(result)
